import { addPlainText, editNote, deleteNote, findNotes, decode, createRepository, ConflictError, STORAGE_KEY } from './notes.js';
import { exportBackup, parseBackup, mergeNotes, downloadBackup, MAX_TRANSFER_BYTES } from './transfer.js';

export function startApp(doc, win, options = {}) {
  const byId = id => doc.getElementById(id);
  const form = byId('note-form');
  const body = byId('note-body');
  const label = byId('note-label');
  const search = byId('search');
  const warning = byId('storage-warning');
  const status = byId('status');
  const list = byId('notes');
  const now = options.now || (() => new Date().toISOString());
  const makeId = options.makeId || (() => win.crypto.randomUUID());
  let notes = [];
  let editingId = null;
  let repository;
  let available = false;
  let dirty = false;
  let editorBaseline = { body: '', label: '' };
  let pendingImport = null;
  let readingFile = false;
  let fileSequence = 0;

  function transferMessage(text) { byId('transfer-status').textContent = text; }
  function updateTransfer() {
    byId('export-notes').disabled = !available;
    byId('import-file').disabled = !available;
    byId('cancel-import').disabled = !pendingImport && !readingFile;
    byId('apply-import').disabled = !available || !pendingImport || readingFile;
    byId('import-preview').hidden = !pendingImport;
    if (pendingImport && available) {
      try {
        pendingImport.plan = mergeNotes(notes, pendingImport.incoming, makeId);
        const plan = pendingImport.plan;
        byId('import-preview').textContent = `추가 ${plan.added}개 · 이미 보관한 메모 ${plan.skipped}개 · 추가 중 번호가 겹쳐 별도 보관 ${plan.copied}개. 기존 ${notes.length}개는 유지됩니다.`;
      } catch (error) {
        pendingImport.plan = null;
        byId('apply-import').disabled = true;
        transferMessage(error.message);
      }
    }
  }

  function say(text) { status.textContent = text; }
  function warn(text) { warning.textContent = text; warning.hidden = !text; }
  function countCharacters() {
    const count = body.value.split(/\r\n|[\r\n\u2028\u2029]/u).filter(line => line.trim()).length;
    byId('char-count').textContent = editingId === null
      ? `${count}개 메모 · ${body.value.length.toLocaleString('ko-KR')} / 100,000자 (한 줄 5,000자)`
      : `${body.value.length.toLocaleString('ko-KR')} / 5,000자`;
  }
  function updateDraftState() {
    dirty = body.value !== editorBaseline.body || (editingId !== null && label.value !== editorBaseline.label);
    byId('edit-label').hidden = editingId === null;
    byId('capture-help').textContent = editingId === null
      ? '한 줄마다 메모 하나로 저장합니다. 빈 줄은 건너뜁니다. 분류 없이 바로 기록하세요.'
      : '지금 선택한 메모만 수정합니다. 줄바꿈도 이 메모 안에 유지됩니다.';
    byId('cancel-edit').hidden = editingId === null && !dirty;
    byId('cancel-edit').textContent = editingId === null ? '입력 취소' : '수정 취소';
    countCharacters();
  }
  function resetEditor() {
    body.value = '';
    label.value = '';
    editingId = null;
    editorBaseline = { body: '', label: '' };
    byId('editor-title').textContent = '바로 기록';
    byId('save-note').textContent = '바로 기록';
    updateDraftState();
  }
  function element(tag, text, className) {
    const result = doc.createElement(tag);
    if (text !== undefined) result.textContent = text;
    if (className) result.className = className;
    return result;
  }
  function render() {
    const found = findNotes(notes, search.value);
    list.replaceChildren();
    byId('note-count').textContent = search.value.trim() ? `${found.length} / ${notes.length}개` : `${notes.length}개`;
    byId('empty-state').hidden = found.length > 0;
    byId('empty-state').replaceChildren(
      element('h3', !available ? '목록을 불러오지 못했습니다' : notes.length ? '일치하는 메모가 없어요' : '첫 메모를 남겨 보세요'),
      element('p', !available ? '위의 저장 안내를 확인해 주세요.' : notes.length ? '다른 단어를 입력하거나 검색을 지워 보세요.' : '짧은 생각도 나중에는 좋은 단서가 됩니다.'),
    );
    byId('save-note').disabled = !available;
    updateTransfer();
    for (const note of found) {
      const item = element('li', undefined, 'note-card');
      const meta = element('div', undefined, 'note-meta');
      if (note.label) meta.append(element('span', note.label, 'note-label'));
      const time = element('time', new Date(note.updatedAt).toLocaleString('ko-KR', { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' }));
      time.dateTime = note.updatedAt;
      time.title = `마지막 수정: ${new Date(note.updatedAt).toLocaleString('ko-KR')}`;
      meta.append(time);
      item.append(meta, element('p', note.body, 'note-body'));
      const actions = element('div', undefined, 'actions note-actions');
      const edit = element('button', '수정');
      edit.type = 'button';
      edit.disabled = !available;
      edit.setAttribute('aria-label', `메모 수정: ${note.body.slice(0, 35)}`);
      edit.addEventListener('click', () => {
        if (dirty && !win.confirm('입력 중인 내용을 버리고 이 메모를 수정할까요?')) return;
        editingId = note.id;
        body.value = note.body;
        label.value = note.label;
        editorBaseline = { body: note.body, label: note.label };
        byId('editor-title').textContent = '메모 수정';
        byId('save-note').textContent = '수정 저장';
        updateDraftState();
        say('내용을 바꾼 뒤 수정 저장을 눌러 주세요.');
        body.focus();
      });
      const remove = element('button', '삭제', 'danger');
      remove.type = 'button';
      remove.disabled = !available;
      remove.setAttribute('aria-label', `메모 삭제: ${note.body.slice(0, 35)}`);
      remove.addEventListener('click', () => {
        if (!win.confirm(`이 메모를 삭제할까요? 되돌릴 수 없습니다.\n\n${note.body.slice(0, 100)}${editingId === note.id && dirty ? '\n\n수정 중인 내용도 닫힙니다.' : ''}`)) return;
        commit(() => deleteNote(notes, note.id), () => {
          if (editingId === note.id) resetEditor();
          say('메모를 삭제했습니다.');
          search.focus();
        });
      });
      actions.append(edit, remove);
      item.append(actions);
      list.append(item);
    }
  }

  function commit(change, after) {
    if (!available) { say('저장 데이터를 다시 불러온 뒤 시도해 주세요.'); return false; }
    let next;
    try { next = change(); } catch (error) { say(error.message); body.focus(); return false; }
    try { repository.save(next); } catch (error) {
      warn(error instanceof ConflictError ? error.message : '저장하지 못했습니다. 저장 공간 또는 브라우저 설정을 확인해 주세요. 입력 중인 내용과 기존 메모는 그대로입니다.');
      say('변경 사항이 저장되지 않았습니다.');
      return false;
    }
    notes = next;
    warn('');
    after();
    render();
    return true;
  }
  function reload(initial = false) {
    try {
      repository ||= createRepository(win.localStorage);
      notes = repository.load();
      available = true;
      warn('');
      if (!initial) say('목록을 다시 불러왔습니다. 입력 중인 내용은 유지했습니다.');
    } catch (error) {
      available = false;
      warn(`메모를 불러올 수 없습니다. ${error.name === 'SecurityError' ? '브라우저의 로컬 저장 권한을 확인해 주세요.' : error.message} 저장과 삭제를 멈췄습니다.`);
    }
    render();
  }
  form.addEventListener('submit', event => {
    event.preventDefault();
    const previousCount = notes.length;
    commit(() => editingId !== null ? editNote(notes, editingId, { body: body.value, label: label.value }, now()) : addPlainText(notes, body.value, makeId, now()), () => {
      const wasEditing = editingId !== null;
      resetEditor();
      say(`${wasEditing ? '수정 내용을' : `메모 ${notes.length - previousCount}개를`} 저장했습니다.${search.value.trim() ? ' 검색 중이라 목록에 보이지 않을 수 있습니다.' : ''}`);
      body.focus();
    });
  });
  body.addEventListener('input', updateDraftState);
  label.addEventListener('input', updateDraftState);
  search.addEventListener('input', render);
  byId('clear-search').addEventListener('click', () => { search.value = ''; render(); search.focus(); });
  byId('cancel-edit').addEventListener('click', () => {
    const wasEditing = editingId !== null;
    if (dirty && !win.confirm(`저장하지 않은 ${wasEditing ? '수정' : '입력'} 내용을 버릴까요?`)) return;
    resetEditor();
    say(`${wasEditing ? '수정' : '입력'}을 취소했습니다. 저장된 메모는 그대로입니다.`);
    body.focus();
  });
  byId('reload-notes').addEventListener('click', () => reload());
  byId('export-notes').addEventListener('click', () => {
    if (!available) return;
    try {
      // Read the latest saved bytes without resetting the editor's conflict baseline.
      const saved = decode(win.localStorage.getItem(STORAGE_KEY));
      const time = now();
      downloadBackup(doc, win, exportBackup(saved, time), `field-notes-${time.replace(/[:.]/g, '-')}.json`);
      transferMessage(`저장된 메모 ${saved.length}개의 다운로드를 요청했습니다. 다운로드 폴더를 확인해 주세요. 작성 중인 초안은 포함하지 않습니다.`);
    } catch (error) { transferMessage(`내보내지 못했습니다. ${error.message}`); }
  });
  byId('import-file').addEventListener('change', async () => {
    const sequence = ++fileSequence;
    const file = byId('import-file').files?.[0];
    pendingImport = null;
    readingFile = false;
    transferMessage('');
    updateTransfer();
    if (!file || !available) return;
    readingFile = true;
    transferMessage('파일을 확인하고 있습니다. 아직 저장하지 않았습니다.');
    updateTransfer();
    try {
      if (file.size > MAX_TRANSFER_BYTES) throw new Error('파일은 10 MiB까지 가져올 수 있습니다.');
      const text = await file.text();
      if (sequence !== fileSequence) return;
      const isPlainText = /\.txt$/i.test(file.name || '') || (!/\.json$/i.test(file.name || '') && file.type === 'text/plain');
      const captured = isPlainText ? addPlainText(notes, text, makeId, now()) : null;
      pendingImport = { incoming: captured ? captured.slice(0, captured.length - notes.length) : parseBackup(text), plan: null };
      transferMessage(`${isPlainText ? '일반 글은 빈 줄을 제외한 한 줄마다 새 메모로 추가합니다. 같은 글을 다시 가져오면 별도 기록이 생깁니다. ' : ''}내용을 확인한 뒤 기존 메모에 추가를 눌러 주세요. 작성 중인 내용은 유지됩니다.`);
    } catch (error) {
      if (sequence !== fileSequence) return;
      transferMessage(`가져오지 못했습니다. ${error.message} 기존 메모는 그대로입니다.`);
    } finally {
      if (sequence === fileSequence) {
        readingFile = false;
        byId('import-file').value = '';
        updateTransfer();
      }
    }
  });
  byId('cancel-import').addEventListener('click', () => {
    fileSequence++;
    readingFile = false;
    pendingImport = null;
    byId('import-file').value = '';
    transferMessage('가져오기를 취소했습니다. 기존 메모와 작성 중인 내용은 그대로입니다.');
    updateTransfer();
  });
  byId('apply-import').addEventListener('click', () => {
    if (!available || readingFile || !pendingImport?.plan) return;
    const plan = pendingImport.plan;
    if (!plan.added) {
      pendingImport = null;
      transferMessage(`추가할 메모가 없습니다. 이미 보관한 메모 ${plan.skipped}개이며 저장 내용은 바꾸지 않았습니다.`);
      updateTransfer();
      return;
    }
    const saved = commit(() => plan.notes, () => {
      pendingImport = null;
      transferMessage(`${plan.added}개를 추가했습니다. 중복 ${plan.skipped}개는 건너뛰었고, 번호가 겹친 ${plan.copied}개는 별도 메모로 보관했습니다. 기존 메모와 작성 중인 내용은 유지했습니다.`);
    });
    if (!saved) transferMessage('가져오기를 저장하지 못했습니다. 저장 안내를 확인해 주세요. 선택한 파일과 작성 중인 내용은 유지됩니다.');
  });
  win.addEventListener('storage', event => {
    if (event.key === STORAGE_KEY || event.key === null) warn('다른 창에서 저장 내용이 바뀌었습니다. 목록 다시 불러오기를 눌러 주세요. 입력 중인 내용은 유지됩니다.');
  });
  win.addEventListener('beforeunload', event => { if (dirty) { event.preventDefault(); event.returnValue = ''; } });
  updateDraftState();
  reload(true);
}

if (typeof document !== 'undefined') startApp(document, window);

