.primary:hover { background: #254630; }
.danger { color: #963b31; }
:focus-visible { outline: 3px solid #a85d1d; outline-offset: 3px; }
.input-hint { color: #626e67; font-size: .78rem; margin: 7px 0 22px; }
#char-count { text-align: right; }
.actions { display: flex; gap: 9px; flex-wrap: wrap; }
.status { font-size: .88rem; margin: 18px 0 0; min-height: 1.6em; overflow-wrap: anywhere; }
.list-heading { display: flex; align-items: baseline; justify-content: space-between; gap: 16px; }
.count { font-size: .85rem; color: #5d6b62; }
