.note-body { white-space: pre-wrap; overflow-wrap: anywhere; margin-bottom: 16px; }
.note-actions { justify-content: flex-end; }
.note-actions button { font-size: .82rem; }
.empty-state { padding: 44px 20px; text-align: center; border: 1px dashed #bbc8b7; border-radius: 11px; color: #55665a; }
.empty-state p { font-size: .88rem; margin-bottom: 0; }
.warning { background: #fff1d8; border: 1px solid #bb823c; padding: 16px; margin-bottom: 18px; border-radius: 8px; overflow-wrap: anywhere; }
.reload { display: block; margin: 20px 0 0 auto; font-size: .8rem; }
.transfer { margin-top: 40px; padding-top: 26px; border-top: 1px solid #d4ddcf; max-width: 680px; }
.transfer > p { font-size: .88rem; }
