import test from 'node:test';
import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { startApp } from '../app.js';
import { STORAGE_KEY, decode } from '../notes.js';
import { exportBackup, MAX_TRANSFER_BYTES } from '../transfer.js';

// This harness exercises handlers and text nodes, not browser rendering or focus layout.
class Element {
  constructor(tag = 'div') { this.tagName = tag; this.children = []; this.listeners = {}; this.value = ''; this.hidden = false; this.disabled = false; this.attributes = {}; this.textContent = ''; }
  append(...nodes) { this.children.push(...nodes); }
  replaceChildren(...nodes) { this.children = nodes; }
  setAttribute(key, value) { this.attributes[key] = value; }
  addEventListener(type, listener) { (this.listeners[type] ||= []).push(listener); }
  emit(type, event = {}) { return Promise.all((this.listeners[type] || []).map(listener => listener({ preventDefault() {}, ...event }))); }
  focus() { this.focused = true; }
  click() { this.clicked = true; }
  remove() { this.removed = true; }
}
const html = await readFile(new URL('../index.html', import.meta.url), 'utf8');
let fixtureCount = 0;

function fixture(storage, opts = {}) {
  const elements = Object.fromEntries([...html.matchAll(/<[^>]*\bid="([^"]+)"[^>]*>/g)].map(match => {
    const element = new Element();
    element.hidden = /\shidden(?:\s|>)/.test(match[0]);
    return [match[1], element];
  }));
  const doc = { body: new Element('body'), getElementById: id => { assert.ok(elements[id], `Missing HTML id: ${id}`); return elements[id]; }, createElement: tag => new Element(tag) };
  const win = new Element();
  const downloads = [];
  const revoked = [];
  win.Blob = Blob;
  win.URL = { createObjectURL(blob) { const url = `blob:test-${downloads.length}`; downloads.push({ blob, url }); return url; }, revokeObjectURL(url) { revoked.push(url); } };
  win.setTimeout = callback => callback();
  let raw = null;
  win.localStorage = storage || { getItem: () => raw, setItem: (key, value) => { assert.equal(key, STORAGE_KEY); raw = value; } };
  win.confirm = () => true;
  if (opts.blocked) Object.defineProperty(win, 'localStorage', { get() { const error = new Error('blocked'); error.name = 'SecurityError'; throw error; } });
  let ids = 0;
  const fixtureId = ++fixtureCount;
  startApp(doc, win, { now: () => '2026-10-17T00:00:00.000Z', makeId: () => `${fixtureId}-${++ids}` });
  const ui = id => elements[id];
  const write = (body, label = '') => { ui('note-body').value = body; ui('note-body').emit('input'); ui('note-label').value = label; ui('note-label').emit('input'); };
  const save = () => ui('note-form').emit('submit');
  const actions = index => ui('notes').children[index].children.at(-1).children;
  return { ui, win, doc, downloads, revoked, write, save, actions, stored: () => decode(win.localStorage.getItem(STORAGE_KEY)) };
}

test('UI create → search → edit → cancel → delete → reload uses storage', () => {
  const app = fixture();
  app.write('가상 점검 A', '현장'); app.save();
  app.write('가상 아이디어 B', '생각'); app.save();
  assert.equal(app.ui('notes').children.length, 2);
  app.ui('search').value = '점검'; app.ui('search').emit('input');
  assert.equal(app.ui('notes').children.length, 1);
  app.actions(0)[0].emit('click');
  assert.equal(app.ui('note-body').value, '가상 점검 A');
  app.write('가상 점검 A 수정', '현장'); app.save();
  assert.equal(app.stored().find(n => n.label === '현장').body, '가상 점검 A 수정');
  app.actions(0)[0].emit('click'); app.write('취소할 수정');
  app.ui('cancel-edit').emit('click');
  assert.equal(app.stored().find(n => n.label === '현장').body, '가상 점검 A 수정');
  app.win.confirm = () => false;
  app.actions(0)[1].emit('click');
  assert.equal(app.stored().length, 2);
  app.win.confirm = () => true;
  app.actions(0)[1].emit('click');
  assert.equal(app.stored().length, 1);
  assert.equal(app.ui('empty-state').hidden, false);
  app.ui('clear-search').emit('click');
  assert.equal(app.ui('notes').children.length, 1);
  const reopened = fixture(app.win.localStorage);
  assert.equal(reopened.ui('notes').children.length, 1);
  assert.equal(reopened.stored()[0].body, '가상 아이디어 B');
});

test('quota failure keeps draft and visible previous notes, retry succeeds', () => {
  const app = fixture();
  app.write('가상 기존 메모'); app.save();
  const normalWrite = app.win.localStorage.setItem;
  app.win.localStorage.setItem = () => { throw new Error('quota'); };
  app.write('가상 새 초안'); app.save();
  assert.equal(app.ui('note-body').value, '가상 새 초안');
  assert.equal(app.ui('notes').children.length, 1);
  assert.match(app.ui('status').textContent, /저장되지/);
  assert.equal(app.ui('storage-warning').hidden, false);
  app.win.localStorage.setItem = normalWrite;
  app.save();
  assert.equal(app.stored().length, 2);
});

test('failed deletion and failed edit retain persisted and visible content', () => {
  const app = fixture();
  app.write('가상 원문'); app.save();
  app.win.localStorage.setItem = () => { throw new Error('quota'); };
  app.actions(0)[1].emit('click');
  assert.equal(app.ui('notes').children.length, 1);
  app.actions(0)[0].emit('click'); app.write('가상 수정'); app.save();
  assert.equal(app.stored()[0].body, '가상 원문');
  assert.equal(app.ui('note-body').value, '가상 수정');
});

test('damaged storage and denied storage disable writes without clearing data', () => {
  let writes = 0;
  const app = fixture({ getItem: () => '{bad', setItem: () => { writes++; } });
  assert.equal(app.ui('save-note').disabled, true);
  app.write('가상 초안'); app.save();
  assert.equal(writes, 0);
  assert.match(app.ui('storage-warning').textContent, /손상/);
  const denied = fixture(null, { blocked: true });
  assert.equal(denied.ui('save-note').disabled, true);
  assert.match(denied.ui('storage-warning').textContent, /권한/);
});

test('other-tab change blocks stale save, reload preserves draft', () => {
  const app = fixture();
  app.write('가상 첫 메모'); app.save();
  const other = fixture(app.win.localStorage);
  other.actions(0)[0].emit('click'); other.write('가상 다른 창 변경'); other.save();
  app.write('가상 작성 중'); app.save();
  assert.match(app.ui('storage-warning').textContent, /다른 창/);
  app.ui('reload-notes').emit('click');
  assert.equal(app.ui('note-body').value, '가상 작성 중');
  app.save();
  assert.equal(app.stored().length, 2);
  assert.equal(app.stored()[1].body, '가상 다른 창 변경');
});

test('draft replacement and cancel respect confirmation; unload detects unsaved input', () => {
  const app = fixture();
  app.write('가상 저장된 메모'); app.save();
  app.write('가상 초안');
  app.win.confirm = () => false;
  app.actions(0)[0].emit('click');
  assert.equal(app.ui('note-body').value, '가상 초안');
  let prevented = false;
  app.win.emit('beforeunload', { preventDefault() { prevented = true; } });
  assert.equal(prevented, true);
  app.win.confirm = () => true;
  app.actions(0)[0].emit('click'); app.write('가상 수정 중');
  app.win.confirm = () => false;
  app.ui('cancel-edit').emit('click');
  assert.equal(app.ui('note-body').value, '가상 수정 중');
});

test('HTML-like note content stays a literal text node', () => {
  const app = fixture();
  const literal = '<img src=x onerror="alert(1)">가상 메모';
  app.write(literal, '<script>가상</script>'); app.save();
  const card = app.ui('notes').children[0];
  assert.equal(card.children[1].textContent, literal);
  assert.equal(card.children[1].children.length, 0);
});

test('new draft can be cancelled and rewritten without changing saved records', () => {
  const app = fixture();
  app.write('가상 보존할 원문', '기존'); app.save();
  const original = app.win.localStorage.getItem(STORAGE_KEY);
  app.write('가상 취소할 새 초안', '임시');
  assert.equal(app.ui('cancel-edit').hidden, false);
  assert.equal(app.ui('cancel-edit').textContent, '입력 취소');
  app.win.confirm = () => false;
  app.ui('cancel-edit').emit('click');
  assert.equal(app.ui('note-body').value, '가상 취소할 새 초안');
  app.win.confirm = () => true;
  app.ui('cancel-edit').emit('click');
  assert.equal(app.win.localStorage.getItem(STORAGE_KEY), original);
  assert.equal(app.ui('note-body').value, '');
  assert.equal(app.ui('note-label').value, '');
  assert.equal(app.ui('cancel-edit').hidden, true);
  app.write('가상 다시 쓰기', '새 기록'); app.save();
  assert.equal(app.stored().length, 2);
  assert.equal(app.stored()[1].body, '가상 보존할 원문');
});

test('blank new and edited input never changes storage and can be corrected', () => {
  const app = fixture();
  app.write('가상 원문', '원래 분류'); app.save();
  const original = app.win.localStorage.getItem(STORAGE_KEY);
  for (const blank of ['', '  \n\t ']) {
    app.write(blank, '분류만 입력'); app.save();
    assert.equal(app.win.localStorage.getItem(STORAGE_KEY), original);
    assert.match(app.ui('status').textContent, /내용을 입력/);
  }
  app.actions(0)[0].emit('click');
  app.write(' \n ', '바꾼 분류'); app.save();
  assert.equal(app.win.localStorage.getItem(STORAGE_KEY), original);
  app.write('가상 유효한 수정', '바꾼 분류'); app.save();
  assert.equal(app.stored().length, 1);
  assert.equal(app.stored()[0].body, '가상 유효한 수정');
});

test('cancel edit then create and edit again never reuses the cancelled edit target', () => {
  const app = fixture();
  app.write('가상 저장 원문', '보존'); app.save();
  const oldId = app.stored()[0].id;
  const original = app.win.localStorage.getItem(STORAGE_KEY);
  app.actions(0)[0].emit('click'); app.write('가상 취소할 수정', '취소');
  app.ui('cancel-edit').emit('click');
  assert.equal(app.win.localStorage.getItem(STORAGE_KEY), original);
  app.write('가상 새 메모', '새 분류'); app.save();
  assert.equal(app.stored().length, 2);
  assert.equal(app.stored().find(note => note.id === oldId).body, '가상 저장 원문');
  app.ui('search').value = '저장 원문'; app.ui('search').emit('input');
  app.actions(0)[0].emit('click'); app.write('가상 확정 수정', '보존'); app.save();
  assert.equal(app.stored().length, 2);
  assert.equal(app.stored().find(note => note.id === oldId).body, '가상 확정 수정');
});

test('reinitializing app during an edit restores only saved data and allows new writing', () => {
  const app = fixture();
  app.write('가상 저장 원문', '보존'); app.save();
  const original = app.win.localStorage.getItem(STORAGE_KEY);
  app.actions(0)[0].emit('click'); app.write('가상 미저장 수정', '임시');
  app.win.emit('beforeunload');
  assert.equal(app.win.localStorage.getItem(STORAGE_KEY), original);
  const reopened = fixture(app.win.localStorage);
  assert.equal(reopened.stored()[0].body, '가상 저장 원문');
  assert.equal(reopened.ui('note-body').value, '');
  reopened.write('가상 재진입 후 새 메모'); reopened.save();
  assert.equal(reopened.stored().length, 2);
  assert.equal(reopened.stored()[1].body, '가상 저장 원문');
});

test('returning editor values to their original text clears the discard warning', () => {
  const app = fixture();
  app.write('가상 원문', '분류'); app.save();
  app.actions(0)[0].emit('click');
  app.write('가상 다른 내용', '임시');
  app.write('가상 원문', '');
  let prevented = false;
  app.win.emit('beforeunload', { preventDefault() { prevented = true; } });
  assert.equal(prevented, false);
  app.win.confirm = () => { throw new Error('unchanged edit should not ask for confirmation'); };
  app.ui('cancel-edit').emit('click');
  assert.equal(app.ui('note-body').value, '');
});

test('malformed reload preserves raw data and current draft until an explicit valid reload', () => {
  const app = fixture();
  app.write('가상 원문', '보존'); app.save();
  const original = app.win.localStorage.getItem(STORAGE_KEY);
  app.actions(0)[0].emit('click'); app.write('가상 작성 중인 수정', '임시');
  const malformed = JSON.stringify({ version: 1, notes: [{ id: 'x', body: 42 }] });
  app.win.localStorage.setItem(STORAGE_KEY, malformed);
  app.ui('reload-notes').emit('click');
  assert.equal(app.ui('save-note').disabled, true);
  assert.equal(app.ui('notes').children.length, 1);
  assert.equal(app.ui('note-body').value, '가상 작성 중인 수정');
  app.save();
  assert.equal(app.win.localStorage.getItem(STORAGE_KEY), malformed);
  app.win.localStorage.setItem(STORAGE_KEY, original);
  app.ui('reload-notes').emit('click');
  assert.equal(app.ui('save-note').disabled, false);
  app.ui('cancel-edit').emit('click');
  assert.equal(app.win.localStorage.getItem(STORAGE_KEY), original);
});

const transferTime = '2026-10-17T00:00:00.000Z';
const transferredNote = (id, body = '가상 파일 메모') => ({ id, body, label: '파일 분류', createdAt: transferTime, updatedAt: transferTime });
const backupFile = notes => {
  const text = exportBackup(notes, transferTime);
  return { size: new TextEncoder().encode(text).byteLength, text: async () => text };
};
async function chooseFile(app, file) {
  app.ui('import-file').files = file ? [file] : [];
  await app.ui('import-file').emit('change');
}

test('export downloads all saved notes, excludes draft, and leaves stale-write detection intact', async () => {
  const app = fixture();
  app.write('가상 저장 메모'); app.save();
  const original = app.stored()[0];
  app.ui('search').value = '결과 없음'; app.ui('search').emit('input');
  app.write('가상 미저장 초안');
  const newer = { ...original, body: '가상 다른 창의 최신 메모' };
  app.win.localStorage.setItem(STORAGE_KEY, JSON.stringify({ version: 1, notes: [newer] }));
  await app.ui('export-notes').emit('click');
  assert.equal(app.downloads.length, 1);
  assert.deepEqual(JSON.parse(await app.downloads[0].blob.text()).notes, [newer]);
  assert.deepEqual(app.revoked, [app.downloads[0].url]);
  const link = app.doc.body.children.at(-1);
  assert.equal(link.clicked, true);
  assert.equal(link.removed, true);
  assert.match(link.download, /^field-notes-.*\.json$/);
  assert.match(app.ui('transfer-status').textContent, /다운로드를 요청/);
  assert.equal(app.ui('note-body').value, '가상 미저장 초안');
  app.save();
  assert.match(app.ui('storage-warning').textContent, /다른 창/);
});

test('file import previews counts, preserves an editing draft, and writes once only on apply', async () => {
  const app = fixture();
  app.write('가상 기존 원문'); app.save();
  app.actions(0)[0].emit('click'); app.write('가상 미저장 수정');
  const original = app.win.localStorage.getItem(STORAGE_KEY);
  let writes = 0;
  const write = app.win.localStorage.setItem;
  app.win.localStorage.setItem = (...args) => { writes++; write(...args); };
  await chooseFile(app, backupFile([transferredNote('imported')]));
  assert.equal(app.win.localStorage.getItem(STORAGE_KEY), original);
  assert.match(app.ui('import-preview').textContent, /추가 1개/);
  await app.ui('apply-import').emit('click');
  assert.equal(writes, 1);
  assert.equal(app.stored().length, 2);
  assert.equal(app.stored()[0].body, '가상 기존 원문');
  assert.equal(app.ui('note-body').value, '가상 미저장 수정');
  app.save();
  assert.equal(app.stored().length, 2);
  assert.equal(app.stored()[0].body, '가상 미저장 수정');
  const reopened = fixture(app.win.localStorage);
  assert.equal(reopened.stored()[1].body, '가상 파일 메모');
});

test('duplicate, conflicting and empty imports never replace existing records', async () => {
  const app = fixture();
  app.write('가상 기존 내용'); app.save();
  const existing = app.stored()[0];
  const original = app.win.localStorage.getItem(STORAGE_KEY);
  await chooseFile(app, backupFile([existing])); await app.ui('apply-import').emit('click');
  assert.equal(app.win.localStorage.getItem(STORAGE_KEY), original);
  const conflict = { ...existing, body: '가상 번호 충돌 내용' };
  await chooseFile(app, backupFile([conflict]));
  assert.match(app.ui('import-preview').textContent, /별도 보관 1개/);
  await app.ui('apply-import').emit('click');
  assert.equal(app.stored().length, 2);
  assert.deepEqual(app.stored()[0], existing);
  assert.equal(app.stored()[1].body, conflict.body);
  assert.notEqual(app.stored()[1].id, existing.id);
  await chooseFile(app, backupFile([conflict])); await app.ui('apply-import').emit('click');
  assert.equal(app.stored().length, 2);
  const merged = app.win.localStorage.getItem(STORAGE_KEY);
  await chooseFile(app, backupFile([])); await app.ui('apply-import').emit('click');
  assert.equal(app.win.localStorage.getItem(STORAGE_KEY), merged);
});

test('invalid, oversized and unreadable files never partially save or erase previous preview safety', async () => {
  const app = fixture();
  app.write('가상 보존 원문'); app.save();
  const original = app.win.localStorage.getItem(STORAGE_KEY);
  const badFiles = [
    { size: 3, text: async () => '{no' },
    { size: MAX_TRANSFER_BYTES + 1, text: async () => { throw new Error('must not read oversize file'); } },
    { size: 0, text: async () => { throw new Error('읽기 실패'); } },
    { size: 1, text: async () => JSON.stringify({ format: 'field-notes', version: 1, exportedAt: transferTime, notes: [transferredNote('a'), { id: 'b', body: '' }] }) },
  ];
  for (const file of badFiles) {
    await chooseFile(app, backupFile([transferredNote('valid-preview')]));
    await chooseFile(app, file);
    assert.equal(app.ui('apply-import').disabled, true);
    await app.ui('apply-import').emit('click');
    assert.equal(app.win.localStorage.getItem(STORAGE_KEY), original);
    assert.match(app.ui('transfer-status').textContent, /가져오지 못했습니다/);
  }
});

test('cancelled and superseded asynchronous reads cannot apply an old file', async () => {
  const app = fixture();
  let finishRead;
  const delayed = { size: 50, text: () => new Promise(resolve => { finishRead = resolve; }) };
  const oldRead = chooseFile(app, delayed);
  await app.ui('cancel-import').emit('click');
  finishRead(exportBackup([transferredNote('cancelled')], transferTime));
  await oldRead;
  assert.equal(app.ui('apply-import').disabled, true);
  assert.equal(app.stored().length, 0);
  const supersededRead = chooseFile(app, delayed);
  await chooseFile(app, backupFile([transferredNote('newest')]));
  finishRead(exportBackup([transferredNote('superseded')], transferTime));
  await supersededRead;
  await app.ui('apply-import').emit('click');
  assert.deepEqual(app.stored().map(n => n.id), ['newest']);
});

test('quota failure and other-tab conflict keep import pending and preserve all previous data', async () => {
  const app = fixture();
  app.write('가상 기존 원문'); app.save();
  const original = app.win.localStorage.getItem(STORAGE_KEY);
  await chooseFile(app, backupFile([transferredNote('from-file')]));
  const write = app.win.localStorage.setItem;
  app.win.localStorage.setItem = () => { throw new Error('quota'); };
  await app.ui('apply-import').emit('click');
  assert.equal(app.win.localStorage.getItem(STORAGE_KEY), original);
  assert.equal(app.ui('apply-import').disabled, false);
  app.win.localStorage.setItem = write;
  const external = [...app.stored(), transferredNote('other-tab')];
  write(STORAGE_KEY, JSON.stringify({ version: 1, notes: external }));
  await app.ui('apply-import').emit('click');
  assert.deepEqual(app.stored(), external);
  assert.match(app.ui('storage-warning').textContent, /다른 창/);
  await app.ui('reload-notes').emit('click');
  await app.ui('apply-import').emit('click');
  assert.equal(app.stored().length, 3);
  assert.deepEqual(app.stored().slice(0, 2), external);
});

test('editing while an import is pending refreshes merge plan instead of discarding the new save', async () => {
  const app = fixture();
  await chooseFile(app, backupFile([transferredNote('from-file')]));
  app.write('가상 파일 확인 후 작성'); app.save();
  await app.ui('apply-import').emit('click');
  assert.equal(app.stored().length, 2);
  assert.equal(app.stored()[0].body, '가상 파일 확인 후 작성');
});

test('malformed local storage blocks import and export without overwriting raw content', async () => {
  const app = fixture({ getItem: () => '{broken', setItem() { throw new Error('must not write'); } });
  assert.equal(app.ui('export-notes').disabled, true);
  assert.equal(app.ui('import-file').disabled, true);
  await chooseFile(app, backupFile([transferredNote('from-file')]));
  await app.ui('export-notes').emit('click');
  await app.ui('apply-import').emit('click');
  assert.equal(app.downloads.length, 0);
  assert.equal(app.win.localStorage.getItem(STORAGE_KEY), '{broken');
});

test('paste once, record once, search content and edit only one resulting note', () => {
  const app = fixture();
  assert.equal(app.ui('edit-label').hidden, true);
  let writes = 0;
  const write = app.win.localStorage.setItem;
  app.win.localStorage.setItem = (...args) => { writes++; write(...args); };
  app.write('가상 현장 A 안내판\r\n\r\n가상 현장 B 출입문\n가상 현장 C 바닥');
  assert.match(app.ui('char-count').textContent, /3개 메모/);
  app.save();
  assert.equal(writes, 1);
  assert.match(app.ui('status').textContent, /메모 3개를 저장/);
  assert.equal(app.ui('note-body').value, '');
  const before = app.stored();
  assert.deepEqual(before.map(note => note.label), ['', '', '']);
  assert.deepEqual(app.ui('notes').children.map(card => card.children[1].textContent), before.map(note => note.body));
  app.ui('search').value = 'B 출입문'; app.ui('search').emit('input');
  assert.equal(app.ui('notes').children.length, 1);
  app.actions(0)[0].emit('click');
  app.write('가상 현장 B 출입문 수정\n가상 추가 확인'); app.save();
  const after = app.stored();
  assert.equal(after.length, 3);
  assert.deepEqual(after[0], before[0]);
  assert.deepEqual(after[2], before[2]);
  assert.equal(after[1].id, before[1].id);
  assert.equal(after[1].body, '가상 현장 B 출입문 수정\n가상 추가 확인');
  assert.deepEqual(fixture(app.win.localStorage).stored(), after);
});

test('invalid batch, quota failure and stale save retain the entire draft without partial writes', () => {
  const app = fixture();
  app.write('가상 기존 메모'); app.save();
  const original = app.win.localStorage.getItem(STORAGE_KEY);
  const invalid = `가상 정상 줄\n${'가'.repeat(5001)}`;
  app.write(invalid); app.save();
  assert.equal(app.win.localStorage.getItem(STORAGE_KEY), original);
  assert.equal(app.ui('note-body').value, invalid);
  assert.match(app.ui('status').textContent, /2번째 줄/);
  const batch = '가상 새 메모 A\n가상 새 메모 B';
  const normalWrite = app.win.localStorage.setItem;
  app.win.localStorage.setItem = () => { throw new Error('quota'); };
  app.write(batch); app.save();
  assert.equal(app.win.localStorage.getItem(STORAGE_KEY), original);
  assert.equal(app.ui('note-body').value, batch);
  app.win.localStorage.setItem = normalWrite;
  const other = fixture(app.win.localStorage);
  other.write('가상 다른 창 메모'); other.save();
  const external = app.win.localStorage.getItem(STORAGE_KEY);
  app.save();
  assert.equal(app.win.localStorage.getItem(STORAGE_KEY), external);
  assert.equal(app.ui('note-body').value, batch);
  app.ui('reload-notes').emit('click'); app.save();
  assert.equal(app.stored().length, 4);
});

test('legacy multiline labelled records survive capture, content edits and backup round trip', async () => {
  const legacy = transferredNote('legacy', '가상 이전 여러 줄\n둘째 줄');
  const app = fixture();
  await chooseFile(app, backupFile([legacy])); await app.ui('apply-import').emit('click');
  app.write('가상 새 A\n가상 새 B'); app.save();
  assert.deepEqual(app.stored().find(note => note.id === 'legacy'), legacy);
  app.ui('search').value = legacy.label; app.ui('search').emit('input');
