  assert.equal(app.ui('note-label').value, legacy.label);
  app.ui('note-body').value += '\n가상 추가 줄'; app.ui('note-body').emit('input'); app.save();
  assert.equal(app.stored().length, 3);
  assert.equal(app.stored().find(note => note.id === 'legacy').label, legacy.label);
  await app.ui('export-notes').emit('click');
  const exported = await app.downloads[0].blob.text();
  const other = fixture();
  await chooseFile(other, { name: 'backup.json', size: exported.length, text: async () => exported });
  await other.ui('apply-import').emit('click');
  assert.deepEqual(other.stored(), app.stored());
});

test('plain UTF-8 text file previews, cancels and applies multiple notes without touching draft or existing records', async () => {
  const app = fixture();
  app.write('가상 보존 원문'); app.save();
  const original = app.win.localStorage.getItem(STORAGE_KEY);
  app.write('가상 미저장 입력');
  const text = '\uFEFF가상 TXT 첫 줄\r\n\r\n가상 TXT 둘째 줄';
  const file = { name: '가상.txt', type: '', size: new TextEncoder().encode(text).length, text: async () => text };
  await chooseFile(app, file);
  assert.match(app.ui('import-preview').textContent, /추가 2개/);
  assert.equal(app.win.localStorage.getItem(STORAGE_KEY), original);
  await app.ui('cancel-import').emit('click');
  assert.equal(app.win.localStorage.getItem(STORAGE_KEY), original);
  await chooseFile(app, file); await app.ui('apply-import').emit('click');
  assert.equal(app.stored().length, 3);
