  assert.equal(app.ui('note-body').value, '가상 미저장 입력');
  assert.deepEqual(fixture(app.win.localStorage).stored(), app.stored());
});

test('invalid text file is atomic and malformed JSON never falls back to ordinary text', async () => {
  const app = fixture();
  app.write('가상 원문'); app.save();
  const original = app.win.localStorage.getItem(STORAGE_KEY);
  for (const [name, type, text] of [
    ['invalid.txt', 'text/plain', `가상 정상 줄\n${'x'.repeat(5001)}`],
    ['empty.txt', 'text/plain', ' \r\n'],
    ['invalid.json', 'text/plain', '{broken'],
  ]) {
    await chooseFile(app, { name, type, size: text.length, text: async () => text });
    assert.equal(app.ui('apply-import').disabled, true);
    await app.ui('apply-import').emit('click');
    assert.equal(app.win.localStorage.getItem(STORAGE_KEY), original);
    assert.match(app.ui('transfer-status').textContent, /가져오지 못했습니다/);
  }
});

