import test from 'node:test';
import assert from 'node:assert/strict';
import { addNote, addPlainText, plainTextBodies, CAPTURE_LIMIT, editNote, deleteNote, findNotes, decode, createRepository, ConflictError, STORAGE_KEY } from '../notes.js';

const early = '2026-10-17T01:00:00.000Z';
const later = '2026-10-17T02:00:00.000Z';
function memory(initial = null) {
  const entries = new Map(initial === null ? [] : [[STORAGE_KEY, initial]]);
  return { getItem: key => entries.get(key) ?? null, setItem: (key, value) => entries.set(key, value) };
}
const one = () => addNote([], { body: '가상 현장 A 점검', label: '업무' }, 'a', early);

test('plain text capture splits line endings, ignores blanks and preserves input order without categories', () => {
  const existing = one();
  const before = JSON.stringify(existing);
  const candidates = ['a', 'z', 'b', 'c'];
  const notes = addPlainText(existing, '\uFEFF 가상 첫 줄 \r\n\t\r\n가상 둘째 줄\r가상 셋째 줄\n', () => candidates.shift(), later);
  assert.deepEqual(notes.map(note => note.body), ['가상 첫 줄', '가상 둘째 줄', '가상 셋째 줄', existing[0].body]);
  assert.deepEqual(notes.slice(0, 3).map(note => note.label), ['', '', '']);
  assert.deepEqual(findNotes(notes).map(note => note.id), ['z', 'b', 'c', 'a']);
  assert.equal(JSON.stringify(existing), before);
  assert.deepEqual(plainTextBodies('가상 A\u2028가상 B\u2029가상 C'), ['가상 A', '가상 B', '가상 C']);
});

test('capture validates the whole batch before allocating IDs and never mutates existing records on error', () => {
  const existing = one();
  const before = JSON.stringify(existing);
  let allocated = 0;
  const makeId = () => `new-${++allocated}`;
  assert.throws(() => addPlainText(existing, `가상 정상 줄\n${'x'.repeat(5001)}`, makeId, later), /2번째 줄/);
  assert.throws(() => addPlainText(existing, 'x'.repeat(CAPTURE_LIMIT + 1), makeId, later), /100,000/);
  assert.throws(() => addPlainText(existing, '\n \r\n', makeId, later), /내용을 입력/);
  assert.equal(allocated, 0);
  assert.throws(() => addPlainText(existing, '가상 A\n가상 B', () => 'a', later), /번호/);
  assert.equal(JSON.stringify(existing), before);
  assert.equal(addPlainText(existing, `${'x'.repeat(5000)}\n${'y'.repeat(5000)}`, makeId, later).length, 3);
});

test('add, edit and delete preserve immutable source and creation time', () => {
  const first = one();
  const edited = editNote(first, 'a', { body: '  가상 현장 A 재점검  ', label: ' 확인 ' }, later);
  assert.equal(first[0].body, '가상 현장 A 점검');
  assert.equal(edited[0].body, '가상 현장 A 재점검');
  assert.equal(edited[0].label, '확인');
  assert.equal(edited[0].createdAt, early);
  assert.equal(edited[0].updatedAt, later);
  assert.deepEqual(deleteNote(edited, 'a'), []);
});

test('blank, too long, missing and duplicate notes are rejected', () => {
  assert.throws(() => addNote([], { body: '  \n ', label: '' }, 'a', early), /내용/);
  assert.throws(() => addNote([], { body: 'x'.repeat(5001), label: '' }, 'a', early), /5000/);
  assert.throws(() => addNote([], { body: 'x', label: 'x'.repeat(41) }, 'a', early), /40/);
  assert.throws(() => addNote(one(), { body: 'b', label: '' }, 'a', early), /겹쳤/);
  assert.throws(() => editNote(one(), 'missing', { body: 'b' }, later), /원본/);
  assert.throws(() => deleteNote(one(), 'missing'), /없습니다/);
});

test('search matches body and label, multiple words, normalization and newest first', () => {
  const notes = addNote(one(), { body: '가상 현장 B', label: 'IDEA' }, 'b', later);
  assert.deepEqual(findNotes(notes).map(n => n.id), ['b', 'a']);
  assert.deepEqual(findNotes(notes, '현장   업무').map(n => n.id), ['a']);
  assert.deepEqual(findNotes(notes, 'ｉｄｅａ').map(n => n.id), ['b']);
  assert.deepEqual(findNotes(notes, '존재하지않음'), []);
  assert.equal(findNotes(notes, '  ').length, 2);
  assert.deepEqual(findNotes(editNote(notes, 'a', { body: '최신', label: '' }, '2026-10-17T03:00:00.000Z')).map(n => n.id), ['a', 'b']);
});

test('new repository restores persisted notes, edits and deletions', () => {
  const storage = memory();
  const first = createRepository(storage);
  assert.deepEqual(first.load(), []);
  first.save(one());
  const second = createRepository(storage);
  assert.deepEqual(second.load(), one());
  second.save(editNote(second.load(), 'a', { body: '수정', label: '' }, later));
  assert.equal(createRepository(storage).load()[0].body, '수정');
  second.save([]);
  assert.deepEqual(createRepository(storage).load(), []);
});

test('corrupt, unknown and malformed storage fails closed without changing raw bytes', () => {
  const badValues = ['{', 'null', '{"version":2,"notes":[]}', '{"version":1,"notes":{}}', JSON.stringify({ version: 1, notes: [{ ...one()[0], createdAt: 'yesterday' }] }), JSON.stringify({ version: 1, notes: [...one(), ...one()] })];
  for (const raw of badValues) {
    const storage = memory(raw);
    const repo = createRepository(storage);
    assert.throws(() => repo.load());
    assert.throws(() => repo.save([]), /먼저/);
    assert.equal(storage.getItem(STORAGE_KEY), raw);
  }
});

test('read denial and quota errors propagate without false success', () => {
  assert.throws(() => createRepository({ getItem() { throw new Error('blocked'); } }).load(), /blocked/);
  const storage = memory();
  const repo = createRepository(storage);
  repo.load();
  storage.setItem = () => { throw new Error('quota'); };
  assert.throws(() => repo.save(one()), /quota/);
  assert.deepEqual(decode(storage.getItem(STORAGE_KEY)), []);
});

test('other-tab writes and deletion cause conflict, explicit reload enables next save', () => {
  const storage = memory();
  const a = createRepository(storage);
  const b = createRepository(storage);
  a.load(); b.load();
  a.save(one());
  assert.throws(() => b.save([]), ConflictError);
  assert.deepEqual(b.load(), one());
  b.save(editNote(one(), 'a', { body: '두 번째 창', label: '' }, later));
  assert.throws(() => a.save([]), ConflictError);
  a.load();
  storage.setItem(STORAGE_KEY, null);
  assert.throws(() => a.save(one()), ConflictError);
});

test('failed reload revokes writes until valid data is explicitly loaded again', () => {
  const storage = memory();
  const repo = createRepository(storage);
  repo.load(); repo.save(one());
  const original = storage.getItem(STORAGE_KEY);
  storage.setItem(STORAGE_KEY, '{broken');
  assert.throws(() => repo.load());
  storage.setItem(STORAGE_KEY, original);
  assert.throws(() => repo.save([]), /먼저/);
  assert.equal(storage.getItem(STORAGE_KEY), original);
  assert.deepEqual(repo.load(), one());
  repo.save(editNote(one(), 'a', { body: '가상 복구 뒤 수정', label: '' }, later));
  assert.equal(decode(storage.getItem(STORAGE_KEY))[0].body, '가상 복구 뒤 수정');
});

