import test from 'node:test';
import assert from 'node:assert/strict';
import { createAppServer } from '../server.js';

// Invoke the request handler directly: no network connection or listening socket.
function request(server, url, method = 'GET') {
  return new Promise(resolve => {
    const response = { status: 0, headers: {}, writeHead(status, headers = {}) { this.status = status; this.headers = headers; }, end(body) { resolve({ status: this.status, headers: this.headers, body: body?.toString() }); } };
    server.emit('request', { url, method }, response);
  });
}

test('local asset handler serves entry and modules with correct MIME without opening network', async () => {
  const server = createAppServer();
  const entry = await request(server, '/');
  assert.equal(entry.status, 200);
  assert.match(entry.body, /lang="ko"/);
  assert.match(entry.headers['Content-Security-Policy'], /connect-src 'none'/);
  for (const path of ['/app.js', '/notes.js', '/transfer.js', '/styles.css']) {
    const result = await request(server, path);
    assert.equal(result.status, 200);
    assert.match(result.headers['Content-Type'], path.endsWith('.js') ? /javascript/ : /css/);
  }
  assert.equal((await request(server, '/', 'HEAD')).body, undefined);
});

test('local asset allowlist refuses project records and mutation requests', async () => {
  const server = createAppServer();
  for (const path of ['/BRIEF.md', '/AGENTS.md', '/.git/config', '/../package.json']) assert.equal((await request(server, path)).status, 404);
  assert.equal((await request(server, '/', 'POST')).status, 405);
});

