import test from 'node:test';
import assert from 'node:assert/strict';
import { exportBackup, parseBackup, mergeNotes, MAX_TRANSFER_BYTES } from '../transfer.js';

const time = '2026-10-17T00:00:00.000Z';
const note = (id, body = '가상 현장 기록') => ({ id, body, label: '가상 분류', createdAt: time, updatedAt: time });
const file = notes => exportBackup(notes, time);

test('export/import round trip preserves Unicode, IDs, labels and timestamps', () => {
  const notes = [note('a', '가상 메모\n두 번째 줄 📝'), note('b', '<script>가상 문자열</script>')];
  const text = file(notes);
  assert.equal(JSON.parse(text).format, 'field-notes');
  assert.equal(JSON.parse(text).version, 1);
  assert.deepEqual(parseBackup(text), notes);
  assert.deepEqual(parseBackup('\uFEFF' + text), notes);
  assert.deepEqual(parseBackup(file([])), []);
});

test('malformed JSON, unsupported format/version and invalid members reject the entire file', () => {
  const valid = JSON.parse(file([note('a')]));
  const values = ['{', 'null', '[]', JSON.stringify({ ...valid, format: 'other' }), JSON.stringify({ ...valid, version: 2 }), JSON.stringify({ ...valid, exportedAt: 'today' }), JSON.stringify({ ...valid, notes: {} }), JSON.stringify({ ...valid, notes: [note('a'), { ...note('b'), body: ' ' }] }), JSON.stringify({ ...valid, notes: [note('a'), note('a')] }), JSON.stringify({ ...valid, notes: [{ ...note('a'), secret: 'unknown field' }] }), JSON.stringify({ ...valid, other: true })];
  for (const value of values) assert.throws(() => parseBackup(value));
});

test('oversized content is rejected before parsing', () => {
  assert.throws(() => parseBackup('x'.repeat(MAX_TRANSFER_BYTES + 1)), /10 MiB/);
});

test('merge appends without mutating existing data, skips exact duplicate IDs', () => {
  const existing = [note('a')];
  const original = JSON.stringify(existing);
  const result = mergeNotes(existing, [note('a'), note('b', '가상 다른 메모')], () => 'new-id');
  assert.equal(JSON.stringify(existing), original);
  assert.deepEqual(result.notes, [...existing, note('b', '가상 다른 메모')]);
  assert.deepEqual({ added: result.added, skipped: result.skipped, copied: result.copied }, { added: 1, skipped: 1, copied: 0 });
  assert.equal(mergeNotes(result.notes, [note('a'), note('b', '가상 다른 메모')], () => 'newer').added, 0);
});

test('same-ID different versions are preserved separately and repeat import does not duplicate the copy', () => {
  const existing = [note('a', '가상 현재 내용')];
  const incoming = [note('a', '가상 옮겨온 내용')];
  const result = mergeNotes(existing, incoming, () => 'copy');
  assert.deepEqual(result.notes[0], existing[0]);
  assert.deepEqual(result.notes[1], { ...incoming[0], id: 'copy' });
  assert.equal(result.copied, 1);
  const repeated = mergeNotes(result.notes, incoming, () => 'unused');
  assert.equal(repeated.added, 0);
  assert.equal(repeated.skipped, 1);
});

test('generated IDs cannot steal another imported ID; failure leaves inputs untouched', () => {
  const existing = [note('a', '가상 기존')];
  const incoming = [note('a', '가상 충돌'), note('reserved', '가상 별개')];
  const candidates = ['a', 'reserved', 'copy'];
  const result = mergeNotes(existing, incoming, () => candidates.shift());
  assert.equal(new Set(result.notes.map(n => n.id)).size, 3);
  assert.equal(result.notes[1].id, 'copy');
  const baseline = JSON.stringify({ existing, incoming });
  assert.throws(() => mergeNotes(existing, incoming, () => 'a'), /번호/);
  assert.equal(JSON.stringify({ existing, incoming }), baseline);
});

test('empty import preserves every existing record and different IDs remain distinct', () => {
  const existing = [note('a')];
  assert.deepEqual(mergeNotes(existing, [], () => 'new').notes, existing);
  assert.equal(mergeNotes(existing, [note('b')], () => 'new').added, 1);
});

