import { decode } from './notes.js';

export const MAX_TRANSFER_BYTES = 10 * 1024 * 1024;
const keys = ['id', 'body', 'label', 'createdAt', 'updatedAt'];
const contentKey = note => JSON.stringify([note.body, note.label, note.createdAt, note.updatedAt]);
const copyNote = note => Object.fromEntries(keys.map(key => [key, note[key]]));

function checkSize(text) {
  if (new TextEncoder().encode(text).byteLength > MAX_TRANSFER_BYTES) throw new Error('파일은 10 MiB까지 가져올 수 있습니다. 원본과 기존 메모는 바꾸지 않았습니다.');
}

export function exportBackup(notes, time) {
  const clean = notes.map(copyNote);
  decode(JSON.stringify({ version: 1, notes: clean }));
  const result = JSON.stringify({ format: 'field-notes', version: 1, exportedAt: time, notes: clean }, null, 2);
  checkSize(result);
  return result;
}

export function parseBackup(text) {
  if (typeof text !== 'string') throw new Error('파일 내용을 읽을 수 없습니다.');
  checkSize(text);
  let parsed;
  try { parsed = JSON.parse(text.replace(/^\uFEFF/, '')); } catch { throw new Error('올바른 JSON 파일이 아닙니다. 아무 메모도 가져오지 않았습니다.'); }
  if (!parsed || parsed.format !== 'field-notes' || parsed.version !== 1 || !Array.isArray(parsed.notes) ||
      typeof parsed.exportedAt !== 'string' || Number.isNaN(Date.parse(parsed.exportedAt)) ||
      new Date(parsed.exportedAt).toISOString() !== parsed.exportedAt ||
      Object.keys(parsed).some(key => !['format', 'version', 'exportedAt', 'notes'].includes(key))) {
    throw new Error('이 도구의 버전 1 내보내기 파일이 아닙니다. 아무 메모도 가져오지 않았습니다.');
  }
  const notes = decode(JSON.stringify({ version: 1, notes: parsed.notes }));
  if (notes.some(note => Object.keys(note).some(key => !keys.includes(key)))) throw new Error('지원하지 않는 메모 필드가 있습니다. 파일을 부분적으로 가져오지 않았습니다.');
  return notes.map(copyNote);
}

// Existing notes are never replaced. Conflicting versions get a new identity.
export function mergeNotes(existing, incoming, makeId) {
  decode(JSON.stringify({ version: 1, notes: existing }));
  decode(JSON.stringify({ version: 1, notes: incoming }));
  const byId = new Map(existing.map(note => [note.id, note]));
  const contents = new Set(existing.map(contentKey));
  const reserved = new Set([...existing, ...incoming].map(note => note.id));
  const appended = [];
  let skipped = 0;
  let copied = 0;
  for (const note of incoming) {
    const match = byId.get(note.id);
    if (match && contents.has(contentKey(note))) { skipped++; continue; }
    let id = note.id;
    if (match) {
      id = null;
      for (let attempt = 0; attempt < 20; attempt++) {
        const candidate = makeId();
        if (typeof candidate === 'string' && candidate && !reserved.has(candidate)) { id = candidate; break; }
      }
      if (!id) throw new Error('새 메모 번호를 만들지 못했습니다. 기존 메모는 바꾸지 않았습니다.');
      copied++;
    }
    const addition = { ...copyNote(note), id };
    reserved.add(id);
    byId.set(id, addition);
    contents.add(contentKey(addition));
    appended.push(addition);
  }
  return { notes: [...existing, ...appended], added: appended.length, skipped, copied };
}

export function downloadBackup(doc, win, text, filename) {
  const blob = new win.Blob([text], { type: 'application/json;charset=utf-8' });
  const url = win.URL.createObjectURL(blob);
  const link = doc.createElement('a');
  try {
    link.href = url;
    link.download = filename;
    link.hidden = true;
    doc.body.append(link);
    link.click();
  } finally {
    link.remove();
    win.setTimeout(() => win.URL.revokeObjectURL(url), 1000);
  }
}
